def bounce_generation_command(label,args,cwd_override=None):
    started=time.monotonic()
    result=subprocess.run(args,cwd=cwd_override or repo,text=True,capture_output=True,timeout=120)
    record={'label':label,'argv':args,'cwd':str(cwd_override or repo),'exit':result.returncode,'stdout':result.stdout,'stderr':result.stderr,'durationSeconds':round(time.monotonic()-started,3)}
    streams={}
    for stream in ['stdout','stderr']:
        content=record[stream].encode('utf-8')
        path=bounce_receipt_dir/f'generation-{len(bounce_evidence["generation"]["results"])+1:02d}.{stream}.log'
        path.write_bytes(content)
        streams[stream]={'path':str(path),'bytes':len(content),'sha256':hashlib.sha256(content).hexdigest()}
    record['rawReceipts']=streams
    bounce_evidence['generation']['results'].append(record)
    write(str(repo/'docs/c1-bounce-tests-evidence.json'),json.dumps(bounce_evidence,indent=2)+'\n')
    display(record)
    return result

