with tempfile.TemporaryDirectory(prefix='c1-bounce-runtime-') as temporary:
    root=Path(temporary)
    for name in ['home','tmp','work']:
        (root/name).mkdir()
    environment={'PATH':'/usr/bin:/bin','HOME':str(root/'home'),'TMPDIR':str(root/'tmp'),'LANG':'C.UTF-8'}
    commands=[
      ('Supported npm bounce suite',['npm','test','--','test/session-bounces.test.js'],repo),
      ('Supported JS runner from unrelated cwd',['/usr/bin/node',str(repo/'scripts/run-tests.js'),'test/session-bounces.test.js'],root/'work'),
      ('Direct Node absolute generated bounce JS from unrelated cwd',['/usr/bin/node','--test',str(repo/'test/session-bounces.test.js')],root/'work')
    ]
    for label,args,cwd in commands:
        result=bounce_runtime_command(label,args,environment,cwd)
        counts={title:len(re.findall(r'^✔ '+re.escape(title)+r' \(',result.stdout,re.MULTILINE)) for title in bounce_titles}
        assert len(counts)==14 and all(n==1 for n in counts.values())
        bounce_evidence['runtimeProof']['observations'].append({'label':label,'eachOriginalCaseExecutedOnce':counts,'ownedHomeEntriesAfterRun':sorted(p.name for p in (root/'home').iterdir()),'ownedTmpEntriesAfterRun':sorted(p.name for p in (root/'tmp').iterdir())})
    bounce_runtime_root=str(root)
try:
    Path(bounce_runtime_root).lstat()
    raise AssertionError('Owned runtime root still exists')
except FileNotFoundError:
    bounce_evidence['runtimeProof']['ownedCleanup']={'path':bounce_runtime_root,'observation':'lstat ENOENT after all three successful child exits and TemporaryDirectory cleanup'}
